// These tests pin what a script sees from integer.from_bytes and
// integer.to_bytes: every value, and the whole text of every refusal. They run
// each call as a script does, through the builtin, and compare with a golden
// table written from the code as it was before change C38c. A row that changes
// is a change a script can see.
//
// Update the golden table only on purpose: go test -run TestPin -update.
//
// Revisions:
//   - 2026-11-04 06:52: initial creation
//   - 2026-11-06 22:37: revision history added (C90)
//   - 2026-11-09 11:34: the golden is the GOLDEN table at the end of this file (C114, Q282)
//   - 2026-11-10 00:25: moved to tests/ (C120a, Q311)
package tests

import (
	"errors"
	"flag"
	"fmt"
	"go/format"
	"os"
	"strconv"
	"strings"
	"testing"
	"unicode/utf8"

	"go.starlark.net/starlark"

	"github.com/thebagchi/lark/v1/runtime/common"
	"github.com/thebagchi/lark/v1/runtime/memwatch"
	"github.com/thebagchi/lark/v1/runtime/plugin"
)

const (
	// SOURCE is this file, which holds the GOLDEN table. A test runs in the
	// directory of its package, so the bare name finds the file.
	//
	// Revisions:
	//   - 2026-11-09 11:34: initial creation (C114, Q282)
	//   - 2026-11-10 00:25: moved to tests/ (C120a, Q311)
	SOURCE = "pin_test.go"

	// FAILED marks a refusal in a golden row, and VALUE a result.
	//
	// Revisions:
	//   - 2026-11-04 06:52: initial creation
	//   - 2026-11-06 22:37: revision history added (C90)
	//   - 2026-11-10 00:25: moved to tests/ (C120a, Q311)
	FAILED = "error: "
	VALUE  = "value: "
)

var (
	// UPDATE asks TestPin to write the GOLDEN table.
	//
	// Revisions:
	//   - 2026-11-09 17:05: the flag writes the table, not a file (C114, Q282)
	//   - 2026-11-10 00:25: moved to tests/ (C120a, Q311)
	UPDATE = flag.Bool(
		"update",
		false,
		"write the GOLDEN table of TestPin",
	)
)

// _Pinned is every expression the pin tests run, in a fixed order.
//
// Revisions:
//   - 2026-11-04 00:30: initial creation (C38c)
//   - 2026-11-10 00:25: moved to tests/ (C120a, Q311)
func _Pinned() []string {
	var (
		rows   []string
		orders = []string{
			``,
			`, "big"`,
			`, "little"`,
		}
		signs = []string{
			``,
			`, signed = True`,
			`, signed = False`,
		}
		datas = []string{
			`b""`,
			`b"\x00"`,
			`b"\x01"`,
			`b"\x7f"`,
			`b"\x80"`,
			`b"\xff"`,
			`b"\x01\x02"`,
			`b"\x80\x00"`,
			`b"\x7f\xff"`,
			`b"\xff\xfe"`,
			`b"\x00\x00\x00\x01"`,
			`b"\x80\x00\x00\x00"`,
			`b"\xff\xff\xff\xff"`,
			`b"\x01\x02\x03\x04\x05\x06\x07"`,
			`b"\x00\x00\x00\x00\x00\x00\x00\x00"`,
			`b"\x00\x00\x00\x00\x00\x00\x00\x01"`,
			`b"\x01\x00\x00\x00\x00\x00\x00\x00"`,
			`b"\x7f\xff\xff\xff\xff\xff\xff\xff"`,
			`b"\x80\x00\x00\x00\x00\x00\x00\x00"`,
			`b"\x00\x00\x00\x00\x00\x00\x00\x80"`,
			`b"\xff\xff\xff\xff\xff\xff\xff\xff"`,
			`b"\x01\x02\x03\x04\x05\x06\x07\x08"`,
			`b"\x00\x00\x00\x00\x00\x00\x00\x00\x00"`,
			`b"\x01\x00\x00\x00\x00\x00\x00\x00\x00"`,
			`b"\xff\xff\xff\xff\xff\xff\xff\xff\xff"`,
			`b"\x80\x00\x00\x00\x00\x00\x00\x00\x00"`,
			`b"\x01\x02\x03\x04\x05\x06\x07\x08\x09\x0a\x0b\x0c\x0d\x0e\x0f\x10"`,
			`b"\xff" * 16`,
			`b"\x80" + b"\x00" * 15`,
			`"abc"`,
			`"\x80"`,
			`"é"`,
		}
		numbers = []string{
			`0`,
			`1`,
			`-1`,
			`127`,
			`128`,
			`-128`,
			`-129`,
			`255`,
			`256`,
			`32767`,
			`32768`,
			`-32768`,
			`-32769`,
			`65535`,
			`65536`,
			`2147483647`,
			`2147483648`,
			`-2147483648`,
			`-2147483649`,
			`4294967295`,
			`4294967296`,
			`9223372036854775807`,
			`9223372036854775808`,
			`-9223372036854775808`,
			`-9223372036854775809`,
			`18446744073709551615`,
			`18446744073709551616`,
			`-18446744073709551616`,
			`340282366920938463463374607431768211455`,
			`340282366920938463463374607431768211456`,
			`-170141183460469231731687303715884105728`,
			`-170141183460469231731687303715884105729`,
		}
		widths = []string{
			`0`,
			`-1`,
			`1`,
			`2`,
			`3`,
			`4`,
			`7`,
			`8`,
			`9`,
			`16`,
			`17`,
		}
	)

	for _, data := range datas {
		for _, order := range orders {
			for _, sign := range signs {
				rows = append(
					rows,
					"integer.from_bytes("+data+order+sign+")",
				)
			}
		}
	}

	for _, number := range numbers {
		for _, width := range widths {
			for _, order := range orders {
				for _, sign := range signs {
					rows = append(
						rows,
						"integer.to_bytes("+number+", "+width+
							order+sign+")",
					)
				}
			}
		}
	}

	return append(
		rows,
		_PinnedCalls()...,
	)
}

